INSERT INTO dump_descriptions (base_key, description) VALUES ('savenormalizer', 'Clears the current save’s modded/sandboxed flag and saves it to disk when loaded in the Space Rig.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('betterterminal', 'Replaces Build Terminal flavor text for upgrades, overclocks, and grenades with Karl.gg or Official Wiki text. Weapon and perk descriptions remain unchanged; rebalance mods may conflict (Mint priority -1).') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
